#Controls the Dropdown Menus
def on_select(event, dropdown_id, current_dropdown):
    selected = current_dropdown.get()
    if selected == "":
        # Re-enable all dropdowns
        for _, dd in dropdowns:
            dd.config(state="readonly")
    else:
        # Disable all others
        for _, dd in dropdowns:
            if dd != current_dropdown:
                dd.config(state="disabled")
#Controls what happens when main window is closed
def on_closing(root):
    root.destroy()
    root.quit()
#Controls the Proceed Button
def proceedButton():
    for label_text, dropdown in dropdowns:
        value = dropdown.get()
        if value != "":
            result = f"{label_text}_{value}"
            spherIndentEngine(result)
            root.quit()
            root.destroy()
            break
#Controls the About the Software button/window
def displayAboutInfo():
    #Define the links
    def open_linkPaper(event):
        webbrowser.open_new("https://example.com")
    def open_linkData(event):
        webbrowser.open_new("https://doi.org/10.18434/Mds2-4051")        
    #Define the About Window
    about_window = tk.Toplevel()
    about_window.title("About SpherIndent")
    about_window.geometry("400x525")
    about_window.configure(bg="white")
    about_window.resizable(False, False)  
    #Define Text Widgets (note: if more than one line is used between, add +1 in the label)
    text_widget = tk.Text(about_window, wrap="word", bg="white", font=("Arial", 11), height=6, borderwidth=0)
    text_widget.insert("1.0", "About SpherIndent\n\n", ("bold","center"))
    text_widget.insert("3.0", "The present version of SpherIndent was developed at the Material Measurement Laboratory (MML) in the National Institute of Standards and Technology (NIST), Gaithersburg, MD.\n\n")
    text_widget.insert("5.0", "It was developed by Nicolas A. Alderete and Yvonne Gerbing during 2024-2025.\n\n") 
    text_widget.insert("7.0", "This work was performed with funding from the CHIPS Metrology Program, part of CHIPS for America, National Institute of Standards and Technology, U.S. Department of Commerce.\n\n")        
    text_widget.insert("9.0", "How to cite\n\n", ("bold","center"))  
    text_widget.insert("11.0", "We appreciate recognition of our work by citing the following (click on the links):\n")  
    text_widget.insert("12.0", "Associated Peer Reviewed Publication\n","linkPaper")
    text_widget.insert("13.0", "Associated Data Publication\n\n","linkData")
    text_widget.insert("15.0", "Contact Information\n\n",("bold","center")) 
    text_widget.insert("17.0", "For comments or suggestions write to: nicolas.alderete@nist.gov")
    #Configure the Text Widgets
    text_widget.pack(padx=10, pady=10, fill="both", expand=True)
    text_widget.tag_configure("bold", font=("Arial", 11, "bold"))
    text_widget.tag_configure("center", justify="center")
    text_widget.tag_configure("linkPaper", foreground="blue", underline=1)
    text_widget.tag_configure("linkData", foreground="blue", underline=1)
    text_widget.tag_bind("linkPaper", "<Button-1>", open_linkPaper)
    text_widget.tag_bind("linkData", "<Button-1>", open_linkData)
    text_widget.config(state="disabled")
    # Create a Close Button
    close_btn = tk.Button(about_window, text="Close", font=("Arial", 10, "bold"), command=about_window.destroy)
    close_btn.pack(pady=10)    
