#ExperimentDataFileSelectorandCalibrationFile####################################################################################################################################################
def getDataFile4Analysis():
    root = tk.Tk()
    root.withdraw()
    file_pathFile = filedialog.askopenfilename(title="Select a File to Analyze", filetypes=[("Data Files", "*.xls *.xlsx *.csv")])
    file_pathCal = filedialog.askopenfilename(title="Select a Calibration File to Use", filetypes=[("Calibration Files", "*.pkl")])    
    return file_pathFile, file_pathCal
#PickleFolderCreator#############################################################################################################################################################################
def check_and_create_picklefolder(dirpath, folder_name):    
    # Check if the folder exists
    if not os.path.exists(os.path.join(dirpath, folder_name)):
        # Create the folder if it doesn't exist
        os.makedirs(os.path.join(dirpath, folder_name))
#IterationRepeaterQuestion#######################################################################################################################################################################
def ask_user2repeat():
    root = tk.Tk()
    root.withdraw()
    user_input = messagebox.askyesno("Input", "Do you want to repeat this iteration?")
    root.destroy()
    return user_input
#CalibrationPickleFileDataRetriever##############################################################################################################################################################
def retrieveDatafromCalibrationFile(direct):
    if len(direct)!=0:
        #Open the PandaDataframe to Retrieve Calibration Data if it Exists
        with open(direct, 'rb') as fileCal:
            dataCal = pickle.load(fileCal)
            calfilesMethod = dataCal["Dataframes"][-1]['CalibrationMethod'].iloc[0]
            if "N≥2 Reference Materials [Chudoba Method (2000)]" in calfilesMethod:
                tipRadCal = remove_nans(dataCal["Dataframes"][-1]['CalibrationAverageRadius(nm)'].values.astype(float),0)
                ComplFunction = dataCal["Dataframes"][-1][['CalibrationForceDomain(mN)', 'CalibrationComplianceFunction(nm/mN)']].values.astype(float)
                tipRadFunction = dataCal["Dataframes"][-1][['CalibrationForceDomain(mN)', 'CalibrationRadiusFunction(nm)']].values.astype(float)                   
            elif "N≥2ReferenceMaterials[Li(2013)|Avadanii(2025)Methods]" in calfilesMethod:
                tipRadCal = remove_nans(dataCal["Dataframes"][-1]['CalibrationAverageRadius(nm)'].values.astype(float),0)
                ComplFunction = dataCal["Dataframes"][-1][['CalibrationForceDomain(mN)', 'CalibrationComplianceFunction(nm/mN)']].values.astype(float)
                tipRadFunction = dataCal["Dataframes"][-1][['CalibrationForceDomain(mN)', 'CalibrationRadiusFunction(nm)']].values.astype(float)  
    return ComplFunction, tipRadCal[0]
#Poisson'sRatioPrompter##########################################################################################################################################################################
def SamplePropertiesPrompt(Eguess, Nuguess):
    propGuesses = [None, None]  # Use a mutable object to store the results    
    def next_button_clicked():
        propGuesses[0] = float(entry1.get())
        propGuesses[1] = float(entry2.get())
        root.destroy()   
    root = tk.Tk()
    root.title(" SampleProperties")
    root.geometry("350x100")    
    tk.Label(root, text="Estimated Sample Modulus (GPa):").grid(row=0, column=0, padx=5, pady=5)
    entry1 = tk.Entry(root)
    entry1.insert(0, Eguess)
    entry1.grid(row=0, column=1, padx=5, pady=5)    
    tk.Label(root, text="Sample Poisson's Ratio:").grid(row=1, column=0, padx=5, pady=5)
    entry2 = tk.Entry(root)
    entry2.insert(0, Nuguess)
    entry2.grid(row=1, column=1, padx=5, pady=5)    
    tk.Button(root, text="Next", command=next_button_clicked).grid(row=2, column=0, columnspan=2, padx=5, pady=5)
    root.wait_window() 
    return propGuesses[0], propGuesses[1]
