#ElasticLimitSelector############################################################################################################################################################################   
def elasticLimitSelector(ncalfiles, labelfiles):
    """Creates the hidden root window and then the visible popup."""
    dropdown_vars_ElastLimits = []
    entry_boxes_ElastLimits = []
    result_ElastLimits = []
    def toggle_entry(row_index, *args):
        nonlocal dropdown_vars_ElastLimits, entry_boxes_ElastLimits
        """Enables or disables the entry box based on the dropdown selection."""
        if dropdown_vars_ElastLimits[row_index].get() == "Known Elastic Limit (mN)":
            entry_boxes_ElastLimits[row_index].config(state="normal")
        else:
            entry_boxes_ElastLimits[row_index].delete(0, tk.END)  # Clear the entry
            entry_boxes_ElastLimits[row_index].config(state="disabled")

    def on_submit(popup, root, numfilescal):
        nonlocal dropdown_vars_ElastLimits, entry_boxes_ElastLimits, result_ElastLimits
        """Retrieves and prints all widget values before closing the application."""
        elasticLimitSelections = []
        for i in range(numfilescal):
            if dropdown_vars_ElastLimits[i].get()=='All Elastic':
                elasticLimitSelections.append(np.inf)
            elif dropdown_vars_ElastLimits[i].get()=='Unknwon Elastic Limit':
                elasticLimitSelections.append(np.nan)
            elif dropdown_vars_ElastLimits[i].get()=='Known Elastic Limit (mN)':
                elasticLimitSelections.append(float(entry_boxes_ElastLimits[i].get()))
        result_ElastLimits.append(elasticLimitSelections)
        popup.destroy()
        root.quit()
    # Create the root window but hide it immediately
    root = tk.Tk()
    root.withdraw()
    root.geometry("450x250")
    popup = tk.Toplevel(root)
    popup.title("Elastic Limit Specification")
    popup.grab_set()
    options = ["All Elastic", "Known Elastic Limit (mN)", "Unknwon Elastic Limit"]
    for i in range(ncalfiles):
        # Create a label for the row
        label = ttk.Label(popup, text='File-'+ str(i)+'_'+os.path.basename(labelfiles[i]))
        label.grid(row=i, column=0, padx=10, pady=5, sticky="w")
        # Variable to store the selected dropdown value
        dropdown_var = tk.StringVar(popup)
        dropdown_var.set(options[0])  # Set default value
        dropdown_vars_ElastLimits.append(dropdown_var)
        # Create the dropdown menu
        dropdown = ttk.Combobox(popup, textvariable=dropdown_var, values=options, width=25, state="readonly")
        dropdown.grid(row=i, column=1, padx=10, pady=5)
        # Create the entry box, initially disabled
        entry_box = ttk.Entry(popup, state="disabled")
        entry_box.grid(row=i, column=2, padx=10, pady=5)
        entry_boxes_ElastLimits.append(entry_box)
        # Bind a function to the dropdown
        dropdown_var.trace("w", lambda *args, row_index=i: toggle_entry(row_index))
    # Submit button
    submit_button = ttk.Button(popup, text="Submit", command=lambda: on_submit(popup, root, ncalfiles))
    submit_button.grid(row=ncalfiles+1, columnspan=3, pady=10)
    root.mainloop()
    return result_ElastLimits[0] if result_ElastLimits else None 
#GetUnitsfromData#################################################################################################################################################################################   
def getUnits(pdcols):
    tUnits = pdcols.iloc[0][0]
    sUnits = pdcols.iloc[0][1]
    fUnits = pdcols.iloc[0][2]
    return tUnits, sUnits, fUnits
#CurveSegmentsIdentifier##########################################################################################################################################################################
def findLoadSegments(tdfarray, prom):
    #Compute the peak load and the location (singlestep=0.1)
    loadEndAll, _ = find_peaks(tdfarray[:,1], prominence=prom)   
    loadEnd00=loadEndAll[0]
    #Find load at that location
    ftemplb = np.abs(tdfarray[:loadEnd00+1,1]-0.95*tdfarray[loadEnd00,1]).argmin()
    #Compute the time derivative of the load (NI is load controlled)
    der_A = np.gradient(tdfarray[:,-1],tdfarray[:,0])
    der_Aselect=der_A[ftemplb:loadEnd00+1]
    for i in range(len(der_Aselect) - 1):
        if der_Aselect[i] > 0 and der_Aselect[i + 1] < 0:
            break
    loadEnd0=min(ftemplb+i,loadEnd00)    
    #Perform a piecewise-linear-fit to obtain the end of the unloading segment
    searchZoneBott = len(tdfarray[:,1])
    searchZoneTop = np.abs(tdfarray[loadEnd0:,1]-0.15*tdfarray[loadEnd0,1]).argmin()+loadEnd0
    Apwlf = pwlf.PiecewiseLinFit(tdfarray[searchZoneTop:searchZoneBott,0], tdfarray[searchZoneTop:searchZoneBott,1])
    res = Apwlf.fit(2)
    xbreaks = Apwlf.fit_breaks[:]   
    xbreakIndx = np.argmin(abs(tdfarray[searchZoneTop:searchZoneBott,0]-xbreaks[1])) + searchZoneTop
    unloadEnd0 = xbreakIndx
    #Perform a piecewise-linear-fit to obtain the end of the unloading segment
    searchZoneTop = np.abs(tdfarray[loadEnd0:,1]-0.95*tdfarray[loadEnd0,1]).argmin()+loadEnd0
    Apwlf = pwlf.PiecewiseLinFit(tdfarray[loadEnd0:searchZoneTop,0], tdfarray[loadEnd0:searchZoneTop,1])
    res = Apwlf.fit(2)
    xbreaks = Apwlf.fit_breaks[:]       
    holdEnd0 = np.argmin(abs(tdfarray[loadEnd0:searchZoneTop,0]-xbreaks[1]))+loadEnd0   
    return loadEnd0, holdEnd0, unloadEnd0
#ThermalDriftCorrection###########################################################################################################################################################################
def thermalDriftCorr(array, t0):
    idx = np.abs(array[:,0] - (array[0,0]+t0)).argmin()
    slope, ordinate = np.polyfit(array[idx:,0], array[idx:,1], 1)
    r2dfit = r_squared(array[idx:,1], slope*array[idx:,0]+ordinate)
    return slope, ordinate, idx, r2dfit 
#PopInDetectionAlgorith###########################################################################################################################################################################
def PopInDetection(array):
    smoothingfraction = 0.20
    smoothedArray = sm.nonparametric.lowess(array[:,1], array[:,0], frac=smoothingfraction)
    deltaForce = abs(smoothedArray[:,1]-array[:,1])
    #Find all the departures
    peaks00, _ = find_peaks(deltaForce)
    #Sort departures by prominences
    prominences00=peak_prominences(deltaForce,peaks00)[0]
    sorted_peaks0 = peaks00[np.argsort(prominences00)[::-1]]
    #Take all the peaks below the greatest one
    FDpinsBeforePeak = array[peaks00[peaks00<=sorted_peaks0[0]],:] 
    #After the largest one, select based on the mean
    stdDevMult = 2.0
    departuresAfterGreatestPeak=deltaForce[peaks00[1+np.argmin(abs(peaks00-sorted_peaks0[0]))]:]
    departureMean = np.mean(departuresAfterGreatestPeak[int(0.5*len(departuresAfterGreatestPeak)):])
    departureDev = np.std(departuresAfterGreatestPeak[int(0.5*len(departuresAfterGreatestPeak)):])
    peaks1, _ = find_peaks(departuresAfterGreatestPeak,prominence=departureMean+stdDevMult*departureDev)
    FDpinsAfterPeak=array[peaks00[1+np.argmin(abs(peaks00-sorted_peaks0[0]))]+peaks1,:]
    forcedispdeparts = np.vstack((FDpinsBeforePeak,FDpinsAfterPeak))
    return forcedispdeparts
#HertzFitterforZPCorrection(shifted and with ordinate)############################################################################################################################################
def HertzianForceDepthFunction0(x, t, y, eknown):
    return (4/3)*eknown*(np.maximum(x[0], 0)**0.5)*(np.maximum(t-x[1], 0)**(3/2))+x[2] - y
#HertzFitterwithKnownRadius#######################################################################################################################################################################
def HertzianForceDepthFunction00(x, t, y, tiprad):  
    return ((4/3)*x[0]*(tiprad**0.5)*(np.maximum(t-x[1], 0)**(3/2))+x[2]) - y
#HertzFitterwithKnownRadius#######################################################################################################################################################################
def HertzianForceDepthFunction1(x, t, y, reff):
    return (4/3)*(x[0]*(1e-6))*(reff**0.5)*((t)**1.5)-y
#HertzModelForceGenerators########################################################################################################################################################################
def gen_ForceHertz1(t, Efitted, Reff):
    y = (4/3)*Efitted*(Reff**0.5)*(t**1.5)
    return y 
def gen_ForceHertz2(t, Efitted, Reff, hf):
    y = (4/3)*Efitted*(Reff**0.5)*((t-hf)**1.5)
    return y 
#Oliver-PharrFitter###############################################################################################################################################################################
def OliverPharrUnloadingFunction(x, t, y):
    return x[0]*((t-x[1])**x[2])-y
#Oliver-PharrForceGenerator#######################################################################################################################################################################
def gen_ForceOlPharr(t,fittedvals):
    f = fittedvals.x[0]*((t-fittedvals.x[1])**fittedvals.x[2])
    return f
#HertzFitterUnloadingCurve########################################################################################################################################################################
def HertzianForceDepthFunctionUnloading(x, t, y):
    return ((4/3)*x[0]*((x[1])**0.5)*((t-x[2])**1.5))-y
#HertzUnloadingCurveGenerator#####################################################################################################################################################################
def gen_HertzianForceDepthFunctionUnloading(t,fittedvals0, fittedvals1, fittedvals2):
    return (4/3)*fittedvals0*((fittedvals1)**0.5)*((t-fittedvals2)**1.5)
#Array2DFConverterSingleStep######################################################################################################################################################################
def Array2DataframeSingleStep(array):
    dfarray = pd.DataFrame(array, columns=['Exp_No','Time(s)', 'Displacement(nm)', 'Force(mN)',
                                           'Index End Load Segment', 'Index End Hold Segment', 'Index End Unload Segment',
                                           'Drift Rate(nm/s)', 'PI_D(nm)','PI_F(mN)', 'N_PI',
                                           'h* (nm),P*(mN)', 
                                           'Corrected Displacement(nm)', 'Corrected Force(mN)',
                                           'Index End Load Segment', 'Index End Hold Segment', 'Index End Unload Segment',
                                           'PI_DCorr(nm)','PI_FCorr(mN)',
                                           'AreaLoading(pJ)','AreaUnloading(pJ)','DissipationWork(pJ)','DissipativeIndex',
                                           'HertzianFit_IndModulus(GPa)|SampleModulus(GPa)|R2',
                                           'OPFit_IndModulus(GPa)|OPFit_SampleModulus(GPa)|OPFit_A(mN)|OPFit_hf(nm)|OPFit_m|OPFit_hc(nm)|OPFit_A(nm2)',
                                           'Max. Shear Stress (GPa)',
                                           'Shear Stress Rate (GPa/s)',
                                           'Cumulative Excursion Length (nm)'])
    return dfarray
#Array2DFConverterMultiStep#######################################################################################################################################################################
def Array2DataframeMultiStep(array):
    dfarray = pd.DataFrame(array, columns=['Exp_No','Time(s)', 'Displacement(nm)', 'Force(mN)',
                                           'NCycles', 'Index Load-Hold-Unload Segments',
                                           'Drift Rate(nm/s)', 'PI_1_D(nm)','PI_1_F(mN)','h* (nm)', 'P*(mN)',
                                           'Spacer',                                           
                                           'Corrected Displacement(nm)', 'Corrected Force(mN)',
                                           'Corrected Index Load-Hold-Unload Segments', 
                                           'OPFit_IndModulus(GPa)|OPFit_SampleModulus(GPa)|OPFit_A(mN)|OPFit_hf(nm)|OPFit_m|OPFit_hc(nm)|OPFit_A(nm2)',
                                           'HertzianFit_IndModulus(GPa)|EffectiveRadius(nm)|h0(nm)|R2',
                                           'ContactRadius(nm)','Strain','Stress(GPa)','R2',
                                           'ElasticSlope(GPa)|PlasticSlope(GPa)|YieldStrain|YieldStress(GPa)'])
                                           
    return dfarray
#PopInSelectionPlotter############################################################################################################################################################################
def PopInSelectionPlotter(popDetFlagFD, fdcurve, fdpins, fontfeatures):
    plt.figure(figsize=(10, 7))
    plt.plot(fdcurve[:,0], fdcurve[:,1], '-r', marker='.', label='Loading Segment') 
    if popDetFlagFD==1:
        for k in range(0,len(fdpins[:,0])):
            if k==len(fdpins[:,0])-1:
                plt.plot([fdpins[k,0],fdpins[k,0]],[0,0.99*fdpins[k,1]],color=(0, 0, 0, 0.5), linestyle='dashed', linewidth=1,label='Suggested PopIns')
            else:
                plt.plot([fdpins[k,0],fdpins[k,0]],[0,0.99*fdpins[k,1]],color=(0, 0, 0, 0.5), linestyle='dashed', linewidth=1, label='_Suggested PopIns')                
    rect = patches.Rectangle((plt.gca().get_xlim()[0], plt.gca().get_ylim()[0]), abs(plt.gca().get_xlim()[0]), abs(plt.gca().get_ylim()[0]),
                             color='black', alpha=0.25)
    plt.gca().add_patch(rect)
    plt.text(0.9*plt.gca().get_xlim()[0],0.9*plt.gca().get_ylim()[0], 'Clear all\nPopIns', fontsize=6, ha='left', va='bottom')        
    plt.title('NanoIndentation Curve', fontsize=fontfeatures['TitleFontSize'] )
    plt.xlabel('Indentation Depth (nm)', fontsize=fontfeatures['xylabelFontSize'])
    plt.ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    plt.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    plt.tight_layout()
    #Check if user wants to add new popins   
    coords=[];removalindex=[]
    coords = plt.ginput(100, show_clicks=True, timeout=18000, mouse_add=MouseButton.LEFT,mouse_stop=MouseButton.MIDDLE, mouse_pop=MouseButton.RIGHT)
    if len(coords)>0:
        if any(all(num < 0 for num in sublist) for sublist in coords):
            if len(fdpins)>0:
                fdpins=[]
            coords=[sublist for sublist in coords if not all(num < 0 for num in sublist)]
        if len(coords)>0:
            for w in range(0,len(coords)):
                if popDetFlagFD==1 and len(fdpins)!=0: 
                    removePointsFD=(((fdpins[:,0]-coords[w][0])**2+(fdpins[:,1]-coords[w][1])**2)**0.5)<1
                    fdpins=fdpins[~removePointsFD]
                else:
                    removePointsFD=np.array([False])
                if removePointsFD.any():
                    removalindex.append(w)               
    coords = [item for i, item in enumerate(coords) if i not in removalindex]
    plt.cla()
    plt.plot(fdcurve[:,0], fdcurve[:,1], 'r', label='Loading Segment')  
    if len(fdpins)>0:
        for k in range(0,len(fdpins[:,0])):
            if k==len(fdpins[:,0])-1:
                plt.plot([fdpins[k,0],fdpins[k,0]],[0,0.999*fdpins[k,1]],color=(0., 0., 0., 0.5), linestyle='dashed', linewidth=1,label='Suggested PopIns') 
            else:
                plt.plot([fdpins[k,0],fdpins[k,0]],[0,0.999*fdpins[k,1]],color=(0., 0., 0., 0.5), linestyle='dashed', linewidth=1,label='_Suggested PopIns') 
    plt.title('NanoIndentation Curve', fontsize=fontfeatures['TitleFontSize'] )
    plt.xlabel('Indentation Depth (nm)', fontsize=fontfeatures['xylabelFontSize'])
    plt.ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    plt.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    for w in range(0,len(coords)):
        temp=np.array(coords[w])
        idx=int(0.5*((np.abs(fdcurve -temp)).argmin()))
        coords[w]=(fdcurve[idx,0],fdcurve[idx,1])
    if len(coords)>0:
        for k in range(0,len(coords)):
           plt.plot([coords[k][0],coords[k][0]],[0,0.999*coords[k][1]],color=(0, 0, 0, 0.5), linestyle='dashed', linewidth=1) 
        if len(fdpins)>0:
            tempstack = np.vstack((fdpins,coords))
        else:
            tempstack = np.array(coords)
        sorted_indices = np.argsort(tempstack[:, 0])
        tempstack =tempstack[sorted_indices]
        tempstack=np.unique(tempstack, axis=0)        
        plt.plot(tempstack[0,0], tempstack[0,1], 'xk', markersize=3, markerfacecolor='none')        
    else:
        if len(fdpins)>0:
            tempstack = np.vstack(fdpins)
            sorted_indices = np.argsort(tempstack[:, 0])
            tempstack =tempstack[sorted_indices]
            tempstack=np.unique(tempstack, axis=0)        
            plt.plot(tempstack[0,0], tempstack[0,1], 'xk', markersize=3, markerfacecolor='none')
    plt.show
    plt.close()
    return(coords,fdpins)
#FDCurveSegmentPlottersSingleStep#################################################################################################################################################################
def fdSegmentPlotters(tdfarray, loadEndloc, holdEndloc, unloadEndloc, slopeDrift, ordinateDrift, idxDriftStart, goodnessDriftFit, 
                      driftcorrdisp, dfcorr, loadEndCorrloc, holdEndCorrloc, unloadEndCorrloc, savefigdir, testnum, sampName, fontfeatures):
    fig = plt.figure(figsize=(12, 6.))
    gs = GridSpec(3, 2, figure=fig)
    fig.suptitle('Test ' + str(testnum))
    ax1 = fig.add_subplot(gs[:, 0])  # This spans the first column and both rows
    ax2 = fig.add_subplot(gs[0, 1])  # This is the first row, second column
    ax3 = fig.add_subplot(gs[1, 1])  # This is the second row, second column  
    ax4 = fig.add_subplot(gs[2, 1])  # This is the second row, second column            
    ax1.plot(tdfarray[:,1],tdfarray[:,2],'k', label='Raw Data')
    ax1.plot(tdfarray[loadEndloc,1],tdfarray[loadEndloc,2],'.r',markersize=8)
    ax1.plot(tdfarray[loadEndCorrloc,1],tdfarray[loadEndCorrloc,2],'xr',markersize=8)
    ax1.plot(tdfarray[holdEndloc,1],tdfarray[holdEndloc,2],'.r',markersize=8)
    ax1.plot(tdfarray[unloadEndloc,1],tdfarray[unloadEndloc,2],'.r', label='Segment Points', markersize=8)
    ax1.plot(driftcorrdisp, tdfarray[:,2],'--k', label='Drift Corrected Data')
    ax1.plot(dfcorr[:,0], dfcorr[:,1],'--r', label='ZP & Mach. Comp. Corrected Data')
    ax1.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax1.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax1.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    ax1.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
           
    ax2.plot(tdfarray[:,1],tdfarray[:,2],'k', label='Raw Data')
    ax2.plot(tdfarray[loadEndloc,1],tdfarray[loadEndloc,2],'.r',markersize=8)
    ax2.plot(tdfarray[holdEndloc,1],tdfarray[holdEndloc,2],'.r',markersize=8)
    ax2.plot(tdfarray[unloadEndloc,1],tdfarray[unloadEndloc,2],'.r', label='Segment Points', markersize=8)
    ax2.plot(driftcorrdisp, tdfarray[:,2],'--k', label='Drift Corrected Data')
    ax2.plot(dfcorr[:,0], dfcorr[:,1],'--r', label='ZP & Mach. Comp. Corrected Data')
    ax2.set_xlim([tdfarray[loadEndloc-int(0.15*loadEndloc),1],1.05*tdfarray[loadEndloc,1]])
    ax2.set_ylim([tdfarray[loadEndloc-int(0.15*loadEndloc),2],1.05*tdfarray[loadEndloc,2]])            
    ax2.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax2.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax2.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    ax2.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])    
    ax3.plot(tdfarray[:,1],tdfarray[:,2],'k', label='Raw Data')
    ax3.plot(tdfarray[loadEndloc,1],tdfarray[loadEndloc,2],'.r',markersize=8)
    ax3.plot(tdfarray[holdEndloc,1],tdfarray[holdEndloc,2],'.r',markersize=8)
    ax3.plot(tdfarray[unloadEndloc,1],tdfarray[unloadEndloc,2],'.r', label='Segment Points', markersize=8)
    ax3.plot(driftcorrdisp, tdfarray[:,2],'--k', label='Drift Corrected Data')
    ax3.plot(dfcorr[:,0], dfcorr[:,1],'--r', label='ZP & Mach. Comp. Corrected Data')
    ax3.set_xlim([0.85*tdfarray[-1,1],1.2*tdfarray[unloadEndloc,1]])
    ax3.set_ylim([0.85*tdfarray[-1,2],1.2*tdfarray[unloadEndloc,2]])            
    ax3.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax3.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax3.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])    
    ax3.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])             
    ax4.plot(tdfarray[unloadEndloc:,0],tdfarray[unloadEndloc:,1],'ok', label='Thermal Drift Data')
    ax4.plot(tdfarray[unloadEndloc+idxDriftStart,0],tdfarray[idxDriftStart+unloadEndloc,1],'.r', label='Segment Points', markersize=8)
    ax4.plot(tdfarray[unloadEndloc+idxDriftStart:,0],slopeDrift*tdfarray[unloadEndloc+idxDriftStart:,0]+ordinateDrift, 
             label='Thermal Drift Data Fit(D='+str(round(slopeDrift,5))+'nm/s |'+r'$R^{2}$'+'='+str(round(goodnessDriftFit,3))+')')         
    ax4.set_xlabel('Time (s)', fontsize=fontfeatures['xylabelFontSize'])
    ax4.set_ylabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax4.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    ax4.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'Plt_PhData-Corrs_Test_'+str(testnum+1)+sampName), dpi=300, bbox_inches='tight')  
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'Plt_PhData-Corrs_Test_'+str(testnum+1)+sampName+'.svg'), format = 'svg')       
    axss = [ax1, ax2, ax3, ax4]
    return  axss
#Interactive MultiStep CycleIndetifier############################################################################################################################################################
def NumberofCyclesConfirmation(ncyc, tdfarray, extremepnts, fontfeatures):
    root = tk.Tk()
    root.title("Cycle Identification")
    root.configure(bg='white')
    # Create a label with the number of cycles
    label_frame = tk.Frame(root, bg='white')
    label_frame.pack(padx=10, pady=(10, 0))
    label_text = tk.Label(label_frame, text="SpherIndent has identified: " + str(ncyc) + ' cycles', bg='white', font=('12'))
    label_text.pack(side=tk.LEFT)
    # Create a plot
    plot_frame = tk.Frame(root, bg='white')
    plot_frame.pack(padx=10, pady=(0, 10))
    fig = Figure(figsize=(6, 4), dpi=100)
    ax = fig.add_subplot(111)
    ax.plot(tdfarray[:,2],'k', label='Raw Data')
    ax.plot(extremepnts, tdfarray[extremepnts,2],'x', label='Segment Points')
    ax.set_xlabel('Index', fontsize=fontfeatures['xylabelFontSize'])
    ax.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])             
    ax.legend(loc="upper left", fontsize=fontfeatures['legendFontSize']) 
    ax.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    canvas = FigureCanvasTkAgg(fig, master=plot_frame)
    canvas.draw()
    canvas.get_tk_widget().pack()
    # Create a frame to hold the buttons
    button_frame = tk.Frame(root, bg='white')
    button_frame.pack(padx=10, pady=10)
    # Define a dictionary to map button clicks to flag values
    flag_values = {
        "Undercounting": -1,
        "Overcounting": 1,
        "Correct": 0
    }
    # Create a variable to store the flag value
    flag = tk.IntVar()
    flag.set(None)  # Initialize with None
    # Handle button clicks
    def on_button_click(value):
        flag.set(value)
        root.destroy()
    # Create the buttons
    for text, value in flag_values.items():
        button = tk.Button(button_frame, text=text, command=lambda v=value: on_button_click(v))
        button.pack(side=tk.LEFT, padx=5)
    # Start the Tkinter event loop
    root.wait_window()  # Wait for the window to be destroyed
    # Return the flag value
    return flag.get()
#FDCurveSegmentPlottersMultiStep##################################################################################################################################################################
def fdSegmentPlottersMultiStep(tdfarray, extremepoints, slopeDrift, ordinateDrift, idxDriftStart, goodnessDriftFit, 
                               driftcorrdisp, dfcorr, extremepointscorr, savefigdir, testnum, fontfeatures):
    fig = plt.figure(figsize=(12, 6.))
    fig.suptitle('Test ' + str(testnum))
    gs = GridSpec(2, 2, figure=fig)
    ax1 = fig.add_subplot(gs[:, 0])  # This spans the first column and both rows
    ax2 = fig.add_subplot(gs[0, 1])  # This is the first row, second column
    ax3 = fig.add_subplot(gs[1, 1])  # This is the first row, second column
     
    ax1.plot(tdfarray[:,1],tdfarray[:,2],'k', label='Raw Data')
    ax1.plot(tdfarray[extremepoints,1],tdfarray[extremepoints,2],'.r',markersize=8)
    ax1.plot(driftcorrdisp, tdfarray[:,2],'--k', label='Drift Corrected Data')
    ax1.plot(dfcorr[:,0], dfcorr[:,1],'--r', label='ZP & Mach. Comp. Corrected Data')
    ax1.plot(dfcorr[extremepointscorr,0],dfcorr[extremepointscorr,1],'.r',markersize=8)
    ax1.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax1.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax1.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    ax1.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])

    ax2.plot(tdfarray[:,2],'k', label='Raw Data')
    ax2.plot(extremepoints, tdfarray[extremepoints,2],'x', label='Segment Points')
    ax2.set_xlabel('Index', fontsize=fontfeatures['xylabelFontSize'])
    ax2.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    ax2.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    ax2.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
          
    ax3.plot(tdfarray[extremepoints[-2]:,0],tdfarray[extremepoints[-2]:,1],'ok', label='Thermal Drift Data')
    ax3.plot(tdfarray[extremepoints[-2]+idxDriftStart,0],tdfarray[idxDriftStart+extremepoints[-2],1],'.r', label='Segment Points', markersize=8)
    ax3.plot(tdfarray[extremepoints[-2]+idxDriftStart:,0],slopeDrift*tdfarray[extremepoints[-2]+idxDriftStart:,0]+ordinateDrift, 
             label='Thermal Drift Data Fit(D='+str(round(slopeDrift,5))+'nm/s |'+r'$R^{2}$'+'='+str(round(goodnessDriftFit,3))+')')         
    ax3.set_xlabel('Time (s)', fontsize=fontfeatures['xylabelFontSize'])
    ax3.set_ylabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    ax3.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    ax3.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'Plt_PhData-Corrs_Test_'+str(testnum)), dpi=300, bbox_inches='tight')  
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'Plt_PhData-Corrs_Test_'+str(testnum)+'.svg'), format = 'svg')       
    axss = [ax1, ax2, ax3]
    return  axss
#fdStressStrainPlottersMultiStep##################################################################################################################################################################
def fdStressStrainPlottersMultiStep(array, fittings, savefigdir, testnum, fontfeatures):
    fig, axs = plt.subplots(1,3,figsize=(12, 6.))
    fig.suptitle('Test ' + str(testnum))    
    dispplot=remove_nans(array[:,12],0)
    forceplot=remove_nans(array[:,13],0)
    extrpoints=remove_nans(array[:,14],0)
    extremepoints=extrpoints.astype(int)
           
    axs[0].plot(dispplot,forceplot,'k', label='F-D Curve')
    axs[0].plot(dispplot[extremepoints],forceplot[extremepoints],'.r',markersize=8)
    axs[0].set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    axs[0].set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    axs[0].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    axs[0].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
 
    axs[1].plot(dispplot,forceplot,'k', label='F-D Curve')
    axs[1].plot(dispplot[extremepoints],forceplot[extremepoints],'.r',markersize=8)    
    for u in range(0,int(array[0,4])):
        xfittings=remove_nans(fittings[:,3*u],0)
        yfittings=remove_nans(fittings[:,3*u+1],0)
        if u==int(array[0,4])-1:
            axs[1].plot(xfittings,yfittings,'--r', label='Hertz Fit')
        else:
            axs[1].plot(xfittings,yfittings,'--r')
    axs[1].set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    axs[1].set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    axs[1].legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    axs[1].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])

    strainplot=remove_nans(array[:,-4],0)
    stressplot=remove_nans(array[:,-3],0)
    Emean=np.nanmean(array[:,-6][::5])
    axs[2].plot(strainplot,stressplot,'sb', markersize=8, label='Stress-Strain')
    
    #OLS Regression
    ols = LinearRegression()
    ols.fit(strainplot.reshape(-1, 1), stressplot)
    y_pred_ols = ols.predict(strainplot.reshape(-1, 1))
    r2_ols=r_squared(stressplot, y_pred_ols)
    yieldStrain_ols = (-Emean*0.002-ols.intercept_)/(ols.coef_- Emean)
    yieldStress_ols = Emean*(yieldStrain_ols-0.002)   
    plasSlope_ols = ols.coef_

    #Robust Theil-Sen Regression    
    theil_sen = TheilSenRegressor()
    theil_sen.fit(strainplot.reshape(-1, 1), stressplot)
    y_pred_theil_sen = theil_sen.predict(strainplot.reshape(-1, 1))
    r2_theil_sen=r_squared(stressplot, y_pred_theil_sen)
    yieldStrain_theil_sen = (-Emean*0.002-theil_sen.intercept_)/(theil_sen.coef_- Emean)
    yieldStress_theil_sen = Emean*(yieldStrain_theil_sen-0.002)
    plasSlope_theil_sen = theil_sen.coef_ 
    if plasSlope_theil_sen>0 and plasSlope_ols>0:
        if yieldStress_ols>0. and r2_ols>r2_theil_sen:
            yieldStrain = yieldStrain_ols
            yieldStress = yieldStress_ols   
            plasSlope = plasSlope_ols
            axs[2].plot(np.linspace(yieldStrain,np.max(strainplot),20), ols.coef_*np.linspace(yieldStrain,np.max(strainplot),20)+ols.intercept_, 
                        color='red', label='OLS Regression (' + '$σ_{Y}$='+str(round(yieldStress[0],2))+' GPa)')            
            axs[2].plot(yieldStrain, yieldStress, 'rx',markersize=4)
        elif yieldStress_theil_sen>0. and r2_theil_sen>r2_ols:       
            yieldStrain = yieldStrain_theil_sen
            yieldStress = yieldStress_theil_sen
            plasSlope = plasSlope_theil_sen
            axs[2].plot(np.linspace(yieldStrain,np.max(strainplot),20), theil_sen.coef_*np.linspace(yieldStrain,np.max(strainplot),20)+theil_sen.intercept_, 
                        color='orange', label='Theil-Sen Robust Regression ('+'$σ_{Y}$='+str(round(yieldStress[0],2))+' GPa)')  
            axs[2].plot(yieldStrain, yieldStress, 'x',color='orange',markersize=4)
        else:
            plasSlope=0.;yieldStrain=0.;yieldStress=0.
    elif plasSlope_theil_sen>0 and plasSlope_ols<=0:
        if yieldStress_theil_sen>0.:
            yieldStrain = yieldStrain_theil_sen
            yieldStress = yieldStress_theil_sen
            plasSlope = plasSlope_theil_sen
            axs[2].plot(np.linspace(yieldStrain,np.max(strainplot),20), theil_sen.coef_*np.linspace(yieldStrain,np.max(strainplot),20)+theil_sen.intercept_, 
                        color='orange', label='Theil-Sen Robust Regression ('+'$σ_{Y}$='+str(round(yieldStress[0],2))+' GPa)')  
            axs[2].plot(yieldStrain, yieldStress, 'x',color='orange',markersize=4)
    elif plasSlope_theil_sen<=0 and plasSlope_ols>0: 
        if yieldStress_ols>0.:
            yieldStrain = yieldStrain_ols
            yieldStress = yieldStress_ols   
            plasSlope = plasSlope_ols
            axs[2].plot(np.linspace(yieldStrain,np.max(strainplot),20), ols.coef_*np.linspace(yieldStrain,np.max(strainplot),20)+ols.intercept_, 
                        color='red', label='OLS Regression (' + '$σ_{Y}$='+str(round(yieldStress[0],2))+' GPa)')            
            axs[2].plot(yieldStrain, yieldStress, 'rx',markersize=4)
    else:
        plasSlope=0.;yieldStrain=0.;yieldStress=0.        
  
    axs[2].plot(np.linspace(0,1.1*np.max(strainplot),20),Emean*np.linspace(0,1.1*np.max(strainplot),20),'--k',label='Elastic Path (E='+str(round(Emean,2))+' GPa)')
    axs[2].set_xlabel('Indentation Strain', fontsize=fontfeatures['xylabelFontSize'])
    axs[2].set_ylabel('IndentationStress (GPa)', fontsize=fontfeatures['xylabelFontSize'])
    axs[2].set_xlim(left=0.0, right=1.5*np.max(strainplot))
    axs[2].set_ylim(bottom=-0.1, top=1.25*Emean*1.1*np.max(strainplot))
    axs[2].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    axs[2].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'IndentationCurve_Test_'+str(testnum)), dpi=300, bbox_inches='tight')   
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(savefigdir),'IndentationCurve_Test_'+str(testnum)+'.svg'), format = 'svg')       
    return Emean, plasSlope, yieldStrain, yieldStress, axs 
def fdHertzOPharrPlotter(dfcorr, loadEndCorrloc,holdEndCorrloc, unloadEndCorrloc, fittedloadforce, fittedunloadforce, modulusH, modulusOP, 
                         goodnessH, goodnessOP, opfitconstants, eeff, radiustip, shearstress, popins, saveimgdir, testnum, act, sampName, fontfeatures):
    fig, axs = plt.subplots(1, 1, figsize=(6, 6))
    axs.plot(dfcorr[:loadEndCorrloc+1,0], dfcorr[:loadEndCorrloc+1,1],'or', markersize=2)    
    axs.plot(dfcorr[loadEndCorrloc:unloadEndCorrloc+1,0], dfcorr[loadEndCorrloc:unloadEndCorrloc+1,1],'or', label='Exp. Data', markersize=2, alpha=0.5)   
    if 'Advanced' in act:
        axs.plot(fittedloadforce[:,0], fittedloadforce[:,1],'--k', 
                 label='Hertz Fit(' + r'$E_{sample}$'+'='+str(round(modulusH,1))+' GPa, τ='+str(round(shearstress,2))+' GPa, ' +r'$R^{2}$'+'='+str(round(goodnessH,2))+')')        
        axs.plot(dfcorr[:loadEndCorrloc+1,0], (1e-6)*(4/3)*eeff*((radiustip)**(1/2))*(dfcorr[:loadEndCorrloc+1,0])**(3/2),'-k',alpha=0.5)
    else:
        axs.plot(fittedloadforce[:,0], fittedloadforce[:,1],'--k', 
                 label='Hertz Fit(' + r'$E_{sample}$'+'='+str(round(modulusH,1))+' GPa |' +r'$R^{2}$'+'='+str(round(goodnessH,2))+')')
    if popins.shape[0]!=0:
        axs.plot(popins[:,0],popins[:,1],'kx',markersize=2)
    axs.set_ylim(bottom=-0.01, top=1.1*dfcorr[loadEndCorrloc,1])
    axs.plot(fittedunloadforce[:,0], fittedunloadforce[:,1],'--k', 
             label='O-P Fit(A=' +str(round(opfitconstants[0]*1000,2)) + 'mN,'+ r'$h_{f}$' + '=' +
             str(round(opfitconstants[1],2))+'nm,m=' + str(round(opfitconstants[2],2))+'\n' + r'$E_{sample}$'+'='+
             str(round(modulusOP,1))+' GPa,' +r'$R^{2}$'+'='+str(round(goodnessOP,2))+')')        
    axs.set_title('Test '+str(testnum), fontsize=fontfeatures['TitleFontSize'])
    axs.set_xlabel('Displacement (nm)', fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylabel('Force (mN)', fontsize=fontfeatures['xylabelFontSize'])
    axs.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])  
    axs.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.show()
    plt.savefig(os.path.join(os.path.dirname(saveimgdir),'Plt_PhData-Fits_Test_'+str(testnum+1)+sampName), dpi=300, bbox_inches='tight') 
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(saveimgdir),'Plt_PhData-Fits_Test_'+str(testnum+1)+sampName+'.svg'), format = 'svg')           
    return  axs
