##########BatchCalibrationSpecs####################################################################################################################################################################
def batchCalSpecifications():
    root = tk.Tk()
    root.title("Batch Calibration Specs")
    root.geometry("300x200")
    frame = tk.Frame(root)
    frame.pack(padx=10, pady=10)
    # Store the collected data
    batchCalSpecs = []
    # Create and grid the labels
    tk.Label(frame, text="Number of Reference Materials", font=("Arial", 10, "bold")).grid(row=0, column=0, padx=5, pady=5)
    tk.Label(frame, text="Number of Tuples", font=("Arial", 10, "bold")).grid(row=2, column=0, padx=5, pady=5)
    # Hold a persistent reference to the StringVar by attaching it to the frame
    frame.selected_value = tk.StringVar(root) #
    dropdown = ttk.Combobox(frame, textvariable=frame.selected_value)
    dropdown['values'] = ('', '2', '3', '4')
    dropdown.current(0) # Sets the default value
    dropdown.grid(row=1, column=0, padx=5, pady=5)
    entry = tk.Entry(frame)
    entry.grid(row=3, column=0, padx=5, pady=5)
    entry.insert(0, '100')  # Set default value
    def on_next():
        # Retrieve the final value from the persistent reference
        batchCalSpecs.append((frame.selected_value.get(), entry.get()))
        root.destroy()
    def on_cancel():
        root.destroy()
    button_frame = tk.Frame(frame)
    button_frame.grid(row=4, column=0, columnspan=2, padx=5, pady=15)    
    next_button = tk.Button(button_frame, text="Next", command=on_next)
    next_button.pack(side=tk.LEFT, padx=5)
    cancel_button = tk.Button(button_frame, text="Cancel", command=on_cancel)
    cancel_button.pack(side=tk.LEFT, padx=5)
    root.wait_window()
    # Return the collected data from the shared storage
    return batchCalSpecs    
def batchCalSpecificationsChudoba():
    root = tk.Tk()
    root.title("Batch Calibration Specs")
    root.geometry("300x300")
    frame = tk.Frame(root)
    frame.pack(padx=10, pady=10)
    frame2 = tk.Frame(root)
    frame2.pack(padx=10, pady=0)
    frame3 = tk.Frame(root)
    frame3.pack(padx=10, pady=0)
    # Store the collected data
    batchCalSpecs = []
    # Create and grid the labels
    tk.Label(frame, text="Number of Reference Materials", font=("Arial", 10, "bold")).grid(row=0, column=0, padx=5, pady=5)
    tk.Label(frame, text="Number of Tuples", font=("Arial", 10, "bold")).grid(row=2, column=0, padx=5, pady=5)
    tk.Label(frame2, text="Number of Max. Loads", font=("Arial", 10, "bold")).grid(row=4, column=0, padx=5, pady=5)
    # Hold a persistent reference to the StringVar by attaching it to the frame
    frame.selected_value = tk.StringVar(root)
    dropdown = ttk.Combobox(frame, textvariable=frame.selected_value)
    dropdown['values'] = ('', '2', '3', '4')
    dropdown.current(0) # Sets the default value
    dropdown.grid(row=1, column=0, padx=5, pady=5)
    entry = tk.Entry(frame)
    entry.grid(row=3, column=0, padx=5, pady=5)
    entry.insert(0, '100')  # Set default value
    frame2.selected_value = tk.StringVar(root)
    dropdown2 = ttk.Combobox(frame2, textvariable=frame2.selected_value)
    dropdown2['values'] = ('','1', '2', '3', '4')
    dropdown2.current(0) # Sets the default value
    dropdown2.grid(row=5, column=0, padx=5, pady=5)
    def on_next():
        # Retrieve the final value from the persistent reference
        batchCalSpecs.append((frame.selected_value.get(), entry.get(), frame2.selected_value.get()))
        root.destroy()
    def on_cancel():
        root.destroy()
    button_frame = tk.Frame(frame3)
    button_frame.grid(row=6, column=0, columnspan=2, padx=5, pady=25)    
    next_button = tk.Button(button_frame, text="Next", command=on_next)
    next_button.pack(side=tk.LEFT, padx=5)
    cancel_button = tk.Button(button_frame, text="Cancel", command=on_cancel)
    cancel_button.pack(side=tk.LEFT, padx=5)
    root.wait_window()
    # Return the collected data from the shared storage
    return batchCalSpecs  
##########DirectCalibrationSpecs##################################################################################################################################################################
def directCalInputPrompt():
    root = tk.Tk()
    root.title("Direct Calibration Input")
    root.geometry("305x200")
    tk.Label(root, text="Tip Radius\n(nm)",font=("Arial", 10, "bold")).grid(row=0, column=0, padx=5, pady=5)
    entry1 = tk.Entry(root, width=20)
    entry1.grid(row=1, column=0, padx=5, pady=5)
    tk.Label(root, text="Single Compliance Value\n(nm/mN)", font=("Arial", 10, "bold")).grid(row=0, column=1, padx=5, pady=5)
    entry2 = tk.Entry(root, width=20)
    entry2.grid(row=1, column=1, padx=5, pady=5)
    dircalinputs = []
    def submitCalEntries():
        fl1radius = float(entry1.get())
        fl2compl = float(entry2.get())
        dircalinputs.append((fl1radius, fl2compl))
        root.destroy()
        return dircalinputs
    tk.Button(root, text="Submit", command=submitCalEntries, font=("Arial", 10, "bold")).grid(row=2, column=0, columnspan=2, sticky="ew", padx=50, pady=10)
    tk.Button(root, text="Cancel", command=root.destroy, font=("Arial", 10, "bold")).grid(row=3, column=0, columnspan=2, sticky="ew", padx=50, pady=10)
    root.wait_window()
    if dircalinputs:
        return dircalinputs
    else:
        return None
##########CalibrationCombiner#####################################################################################################################################################################
def getPickleFiles4CalibrationCombiner():
    root = tk.Tk()
    root.withdraw()
    file_paths = filedialog.askopenfilenames(title="Select Pickle Files", filetypes=[("Pickle Files", "*.pkl")])    
    return file_paths
##########CalibrationFilesSelector################################################################################################################################################################
def getDataFile4Calibration(indx):
    root = tk.Tk()
    root.withdraw()
    if indx==0:
        file_path = filedialog.askopenfilename(title="Select 1st File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")])
    elif indx==1:
        file_path = filedialog.askopenfilename(title="Select 2nd File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")])
    elif indx==2:     
        file_path = filedialog.askopenfilename(title="Select 3rd File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")])
    elif indx==3:     
        file_path = filedialog.askopenfilename(title="Select 4th File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")]) 
    else:
        file_path = filedialog.askopenfilename(title="Select "+ str(indx) + "th File for Calibration", filetypes=[("Data Files", "*.xls *.xlsx *.csv")])
    return file_path
##########CalibrationEffectiveRadiusPlotter#######################################################################################################################################################
def plotterEffectiveRadius(nFiles, fVector, hdiffVector, linfit, rad, Rgoodness, rindex, derivative, powerlawfit, RgoodnessPowerLaw, path, axname, selTests, 
                           fontfeatures):
    if nFiles==2:
        labelscombinations = list(combinations(list(range(3)),2))
        axname[0].plot(fVector**(2/3), hdiffVector, 'or', label = 'Exp. Points', markersize=2)
        axname[0].plot(fVector**(2/3), linfit, '--k', 
                       label = 'Fit('+r'$R_{eff}$'+'='+str(round(rad,2))+'nm | '+r'$R^{2}$'+'='+str(round(Rgoodness,3))+')')
        axname[0].set_xlabel(r'$P^{2/3}$'+'('+r'$mN^{2/3}$'+')',fontsize=fontfeatures['xylabelFontSize'])
        axname[0].set_ylabel(r'$h_{'+str(labelscombinations[rindex][0])+'}$' +'-' + r'$h_{'+str(labelscombinations[rindex][1])+'}$'+'(nm)',
                             fontsize=fontfeatures['xylabelFontSize'])
        axname[0].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
        axname[0].set_title('Pair: Material '+str(labelscombinations[rindex][0])+' - Material '+ str(labelscombinations[rindex][1]),
                            fontsize=fontfeatures['xylabelFontSize'])
        axname[0].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
        axname[1].plot(fVector, derivative, 'or', label = 'Exp. Points', markersize=2)
        if RgoodnessPowerLaw>0.8:
            axname[1].plot(fVector, powerlawfit.x[0]*(fVector**powerlawfit.x[1])+powerlawfit.x[2], '--k', 
                           label = 'Fit('+r'$R^{2}$'+'='+str(round(RgoodnessPowerLaw,3))+')')
        axname[1].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize'])
        axname[1].set_ylabel(r'$R_{eff}$'+'(nm)',fontsize=fontfeatures['xylabelFontSize'])
        axname[1].legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])   
        axname[1].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
        plt.tight_layout()
        plt.tight_layout()
        plt.savefig(os.path.join(os.path.dirname(os.path.dirname(path)),'Plt_Calib_FitR'+'-'.join(map(str, selTests))), dpi=300, bbox_inches='tight') 
        plt.rcParams['svg.fonttype'] = 'none'
        plt.savefig(os.path.join(os.path.dirname(os.path.dirname(path)),'Plt_Calib_FitR'+'-'.join(map(str, selTests))+'.svg'), format = 'svg')              
        plt.close('all')      
    elif nFiles==3:
        labelscombinations = list(combinations(list(range(3)),2))
        axname[0,rindex].plot(fVector**(2/3), hdiffVector, 'or', label = 'Exp. Points', markersize=2)
        axname[0,rindex].plot(fVector**(2/3), linfit, '--k', 
                              label = 'Fit('+r'$R_{eff}$'+'='+str(round(rad,2))+'nm | '+r'$R^{2}$'+'='+str(round(Rgoodness,3))+')')
        axname[0,rindex].set_xlabel(r'$P^{2/3}$'+'('+r'$mN^{2/3}$'+')',fontsize=fontfeatures['xylabelFontSize'])
        axname[0,rindex].set_ylabel(r'$h_{'+str(labelscombinations[rindex][0])+'}$' +'-' + r'$h_{'+str(labelscombinations[rindex][1])+'}$'+'(nm)',
                                    fontsize=fontfeatures['xylabelFontSize'])
        axname[0,rindex].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
        axname[0,rindex].set_title('Pair: Material '+str(labelscombinations[rindex][0])+' - Material '+ str(labelscombinations[rindex][1]),
                                   fontsize=fontfeatures['xylabelFontSize'])            
        axname[0,rindex].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
        axname[1,rindex].plot(fVector, abs(derivative), 'or', label = 'Exp. Points', markersize=2)
        if RgoodnessPowerLaw>0.8:
            axname[1,rindex].plot(fVector, powerlawfit.x[0]*(fVector**powerlawfit.x[1])+powerlawfit.x[2], '--k', 
                                  label = 'Fit('+r'$R^{2}$'+'='+str(round(RgoodnessPowerLaw,3))+')')
        axname[1,rindex].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize'])
        axname[1,rindex].set_ylabel(r'$R_{eff}$'+'(nm)',fontsize=fontfeatures['xylabelFontSize'])
        axname[1,rindex].legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
        axname[1,rindex].set_title('Pair: Material '+str(labelscombinations[rindex][0])+' - Material '+ str(labelscombinations[rindex][1]),
                                   fontsize=fontfeatures['xylabelFontSize'])  
        axname[1,rindex].tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
        plt.show()    
        #Save figure
        if rindex==nFiles-1:
            plt.tight_layout()
            plt.savefig(os.path.join(os.path.dirname(os.path.dirname(path)),'Plt_Calib_FitR'+'-'.join(map(str, selTests))), dpi=300, 
                        bbox_inches='tight') 
            plt.rcParams['svg.fonttype'] = 'none'
            plt.savefig(os.path.join(os.path.dirname(os.path.dirname(path)),'Plt_Calib_FitR'+'-'.join(map(str, selTests))+'.svg'), 
                        format = 'svg')              
            plt.close('all')
##########ChudobaMethodPlotter####################################################################################################################################################################
def chudobaPlotter(array,nloadlevels, direcsave, mater, fontfeatures):
    matsUsed = [item.split('-')[1].split('(')[0] for item in mater]
    fig, axs = plt.subplots(1, 4,figsize=(12, 6.))
    for b in range(0,nloadlevels): 
        axs[0].plot(remove_nans(array[b+1,:,0],0),remove_nans(array[b+1,:,1],0),'o', label='Load Level '+str(int(b+1)), markersize=4)
        axs[1].plot(remove_nans(array[b+1,:,0],0),remove_nans(array[b+1,:,2],0),'o', label='Load Level '+str(int(b+1)), markersize=4)
    axs[0].plot(remove_nans(array[0,:,0],0),remove_nans(array[0,:,1],0),'dk', label='Average',markersize=6)
    axs[1].plot(remove_nans(array[0,:,0],0),remove_nans(array[0,:,2],0),'dk', label='Average',markersize=6)
    axs[0].set_title('Tuple Materials: '+'-'.join(map(str, matsUsed)),fontsize=fontfeatures['xylabelFontSize'])
    axs[1].set_title('Tuple Materials: '+'-'.join(map(str, matsUsed)),fontsize=fontfeatures['xylabelFontSize'])
    axs[0].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize'])
    axs[1].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[0].set_ylabel(r'$R(nm)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[1].set_ylabel(r'$C(nm/mN)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[0].tick_params(axis='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    axs[1].tick_params(axis='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    axs[0].legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    axs[1].legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])
    maxForceLabels = np.unique(remove_nans(array[0, :, 0],0))
    violinDataR = [remove_nans(array[i+1, :, 1],0) for i in range(array.shape[0]-1)]
    meansR = [np.mean(y) for y in violinDataR]
    violinDataC = [remove_nans(array[i+1, :, 2],0) for i in range(array.shape[0]-1)]
    meansC = [np.mean(y) for y in violinDataC]
    axs[2].violinplot(violinDataR, showmeans=True)
    axs[2].plot(range(1, len(maxForceLabels) + 1), meansR, 'o--', color='red', markersize=4, lw=1)
    axs[3].violinplot(violinDataC, showmeans=True)
    axs[3].plot(range(1, len(maxForceLabels) + 1), meansC, 'o--', color='red', markersize=4, lw=1)
    axs[2].set_title('Tuple Materials: '+'-'.join(map(str, matsUsed)),fontsize=fontfeatures['xylabelFontSize'])
    axs[3].set_title('Tuple Materials: '+'-'.join(map(str, matsUsed)),fontsize=fontfeatures['xylabelFontSize'])
    axs[2].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize'])
    axs[3].set_xlabel(r'$P(mN)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[2].set_ylabel(r'$R(nm)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[3].set_ylabel(r'$C(nm/mN)$',fontsize=fontfeatures['xylabelFontSize']) 
    axs[2].tick_params(axis='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    axs[3].tick_params(axis='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    axs[2].set_xticks(range(1, len(maxForceLabels) + 1), maxForceLabels)
    axs[3].set_xticks(range(1, len(maxForceLabels) + 1), maxForceLabels)
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join(os.path.dirname(direcsave),'Plt_RadiusComplFun_'+'-'.join(map(str, matsUsed))), dpi=300, bbox_inches='tight') 
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(os.path.dirname(direcsave),'Plt_RadiusComplFun_'+'-'.join(map(str, matsUsed))+'.svg'), format = 'svg')      
    return axs   
##########Optimize B-Splines for Compliance#######################################################################################################################################################            
def residuals_with_splineCFixedR(params, matwithVectors, EffModulis, knotn, kdeg):
    R = params[0]
    spline_coeffs = params[1:]
    if R <= 0:
        return np.full(len(matwithVectors[:,0]) * len(EffModulis), np.inf)
    # Reconstruct the spline function from the coefficients
    t_spline = np.r_[ (matwithVectors[0,0],)*(kdeg+1), knotn, (matwithVectors[-1,0],)*(kdeg+1) ]
    C_P_splineObj = BSpline(t_spline, spline_coeffs, kdeg)
    C_P_spline = C_P_splineObj(matwithVectors[:,0])
    concatList=[]
    # Calculate the residuals for each equation
    for m in range(0,len(EffModulis)):
        concatList.append(matwithVectors[:,m+1]-(((3/4)/((1E-6)*EffModulis[m]))**(2/3)) * ((matwithVectors[:,0])**(2/3)) * (1/np.sqrt(R))**(2/3) - C_P_spline*matwithVectors[:,0])
    # Concatenate all residuals into a single array
    return np.concatenate(concatList)
