#PickleFileSelector################################################################################################################################################################################
def getPickleFile4Analysis():
    root = tk.Tk()
    root.withdraw()   
    file_pathData = filedialog.askopenfilename(title="Select an Analysis File to Use", filetypes=[("Analysis File", "*.pkl")])  
    return file_pathData
#PickleFile2ExcelConverter########################################################################################################################################################################
def ExcelPrompt():
    user_response = messagebox.askyesno("Prompt", "Do you want to convert pickle file to excel?")
