#AverageIndentationCurvePlotter###################################################################################################################################################################
def AverageIndentationCurvePlotter(x, y, stddev, xx, yy, stddevv, sampName, save2dir, fontfeatures):
    fig, axs = plt.subplots(1, 1, figsize=(6, 6))
    axs.plot(x, y, '-b', label='Mean F-D Curve')
    axs.plot(xx, yy, '-b')
    axs.fill_betweenx(y, x - stddev, x + stddev, color='gray', alpha=0.5, label='Mean ± Std Dev')
    axs.fill_betweenx(yy, xx - stddevv, xx + stddevv, color='gray', alpha=0.5, label='Mean ± Std Dev')
    axs.set_xlabel('Indentation Depth (nm)',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylabel('Force (mN)',fontsize=fontfeatures['xylabelFontSize'])
    axs.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])  
    axs.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show()
    plt.savefig(os.path.join((os.path.dirname(save2dir)),'Plt_AvgPhData_'+sampName), dpi=300, bbox_inches='tight') 
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join((os.path.dirname(save2dir)),'Plt_AvgPhData_'+sampName+'.svg'), format = 'svg')  
    return axs     
#ModulusBarChartPlotter###########################################################################################################################################################################
def ModulusBarChartPlotter(EHertz, EOliverPharr, ERef, sampName, save2dir, fontfeatures):
    fig, axs = plt.subplots(1, 1, figsize=(6, 6))
    n = len(EHertz)
    # Set width of bar
    bar_width = 0.35
    # Set position of bar on X axis
    r1 = np.arange(n)
    r2 = [i + bar_width for i in r1] 
    errorHertz = (np.mean(EHertz) - ERef)/ERef
    errorOP = (np.mean(EOliverPharr) - ERef)/ERef
    axs.bar(r1, EHertz, color='b', width=bar_width, edgecolor='grey', 
            label='Hertz ('+r'$E_{Avg}$'+'='+str(round(np.mean(EHertz),2))+' ± '+str(round(np.std(EHertz),2))+' GPa, ε = '+str(round(errorHertz*100,2))+'%)')    
    axs.bar(r2, EOliverPharr, color='r', width=bar_width, edgecolor='grey',
            label='Oliver-Pharr ('+r'$E_{Avg}$'+'='+str(round(np.mean(EOliverPharr),2))+' ± '+str(round(np.std(EOliverPharr),2))+' GPa, ε = '+ str(round(errorOP*100,2))+'%)')
    axs.axhline(y=np.mean(EHertz), color='b', linestyle='--') 
    axs.axhline(y=np.mean(EOliverPharr), color='r', linestyle='--')  
    axs.set_xlabel('Test',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylabel('Modulus (GPa)',fontsize=fontfeatures['xylabelFontSize'])
    # Add xticks on the middle of the group bars
    axs.set_xticks([r + bar_width/2 for r in range(n)], np.arange(n)+1)
    axs.tick_params(axis='both', which='both', direction='in', labelsize=fontfeatures['axTicksFontSize'])    
    axs.legend(fontsize=fontfeatures['xylabelFontSize'],loc='lower left')    
    plt.tight_layout()
    plt.show() 
    plt.savefig(os.path.join((os.path.dirname(save2dir)),'Plt_AvgModuli_'+sampName), dpi=300, bbox_inches='tight')
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join((os.path.dirname(save2dir)),'Plt_AvgModuli_'+sampName+'.svg'), format = 'svg')
    return axs    
#YieldCurvePlotter################################################################################################################################################################################
def yieldPlotter(issAll, elasSlope, sigmayield, plasslopes, nrows, directory, fontfeatures):
    AnalysisRepo = np.full((nrows,7),np.nan)
    fig, axs = plt.subplots(figsize=(12, 5.))   
    axs.plot(issAll[:,0],issAll[:,1],'ok', markersize = 2)
    strainElast = np.linspace(0, np.max(issAll[:,0]),10)
    axs.plot(strainElast,elasSlope*strainElast, '--k', label='Elastic Path ($E_{avg}=$'+str(round(elasSlope,2))+' GPa)')
    #OLS Regression
    ols = LinearRegression()
    ols.fit(issAll[:,0].reshape(-1, 1), issAll[:,1]) 
    r2_ols=r_squared(issAll[:,1], ols.predict(issAll[:,0].reshape(-1, 1)))  
    #Intersection with 0.002 strain ()
    yieldStrain = (-elasSlope*0.002-ols.intercept_)/(ols.coef_-elasSlope)
    yieldStress = elasSlope*(yieldStrain-0.002)   
    axs.plot(np.linspace(yieldStrain,np.max(issAll[:,0]),nrows),
                ols.coef_*np.linspace(yieldStrain,np.max(issAll[:,0]),nrows)+ols.intercept_,
                color='blue',
                label='OLS Regression ($E_{P}$='+str(round(ols.coef_[0],2))+' GPa, ' + '$σ_{Y}$='+str(round(yieldStress[0],2))+' GPa, $R^{2}$='+str(round(r2_ols,2))+')')          
    axs.plot(yieldStrain, yieldStress, 'rx',markersize=4)                 
    axs.set_xlabel('Indentation Strain',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylabel('Indentation Stress (GPa)',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylim(bottom=-0.1, top=1.1*np.max(issAll[:,1]))
    axs.set_xlim(right=0.3)
    axs.legend(loc="upper left",fontsize=fontfeatures['legendFontSize'])        
    axs.tick_params(axis='both', which='major', direction='in', labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show() 
    plt.savefig(os.path.join(directory,'YieldPlotter_'+os.path.splitext(os.path.basename(directory))[0]), dpi=300, bbox_inches='tight')
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(directory,'YieldPlotter_'+os.path.splitext(os.path.basename(directory))[0]+'.svg'), format = 'svg')
    AnalysisRepo[:issAll.shape[0],0:2]=issAll[:,0:2]
    AnalysisRepo[0,2]=yieldStrain
    AnalysisRepo[0,3]=yieldStress
    AnalysisRepo[0:3,4]=np.vstack((ols.coef_, ols.intercept_, r2_ols)).ravel()
    AnalysisRepo[:,5:7]=np.column_stack((np.linspace(yieldStrain,np.max(issAll[:,0]),nrows),ols.coef_*np.linspace(yieldStrain,np.max(issAll[:,0]),nrows)+ols.intercept_))
    return AnalysisRepo, axs        
#IndentMetricsPlotter#############################################################################################################################################################################
def IndentMetricsPlotter(numfiles,vars2plot, resultsArray, numrows, sampName, directory):
    AnalysisRepo = np.full((numrows,3*len(vars2plot)),np.nan)
    colNames=[]
    axsContainer = [None]*len(vars2plot)
    for w in range(0,len(vars2plot)):
        VecZ = np.full((numfiles),np.nan)
        currVar = vars2plot[w]
        xlimits = None        
        match currVar:
            case 'HertzSampleModulus':
                currVarshort='HertzE'
                VecZ[:resultsArray.shape[0]]=resultsArray[:,1,23]
                cblabel = r'$E_{Hertz} (GPa)$' 
                title = 'Sample Modulus (Hertz)'            
            case 'NPopIns':
                currVarshort='NPIns'
                VecZ[:resultsArray.shape[0]]=resultsArray[:,0,10]
                VecZ = np.nan_to_num(VecZ, nan=0)
                cblabel = r'$N_{Pop-Ins}$' 
                title = 'Number of Pop-In Events'
            case 'DissipativeIndex':
                currVarshort='DissIndx'
                VecZ[:resultsArray.shape[0]]=resultsArray[:,0,22]
                cblabel = r'$\eta = 1-W_L/W_T$'
                title = 'Dissipative Index'
            case 'DissipationWork':
                currVarshort='DissW'
                VecZ[:resultsArray.shape[0]]=resultsArray[:,0,21]
                cblabel = r'$W_d = W_L-W_U$ (pJ)'
                title = 'Dissipation Work'                
            case 'ExcursionLength':
                currVarshort='ExcLength'
                VecZ[:resultsArray.shape[0]]=abs(resultsArray[:,0,27])
                title = 'Displacement Burst'
                cblabel = r'$h_{p}-h_{e} (nm)$'  
            case 'HertzGoodnessofFit':
                currVarshort='HertzR2'
                VecZ[:resultsArray.shape[0]]=resultsArray[:,2,23]
                title = 'Goodness of Fit (Hertz)'
                cblabel = r'$R^2$' 
                xlimits = (-1,1)
        colNames.append(cblabel)                     
        fig, axs = plt.subplots(1,1,figsize=(6, 6.))
        sbn.histplot(VecZ, kde=True, bins='auto', stat="percent", ax=axs, color='r')
        axs.tick_params(axis='both', which='major', direction='in')
        axs.set_xlabel(cblabel,fontsize=10)
        axs.set_ylabel('Percent (%)',fontsize=10)     
        axs.set_title(title,fontsize=10)
        if xlimits is not None:
            axs.set_xlim(*xlimits)
        plt.show        
        plt.savefig(os.path.join(directory,'Plt_Histo_'+currVarshort+'_'+sampName), dpi=300, bbox_inches='tight')
        plt.rcParams['svg.fonttype'] = 'none'
        plt.savefig(os.path.join(directory,'Plt_Histo_'+currVarshort+'_'+sampName+'.svg'), format = 'svg') 
        #Retrieve Histrogram Data
        AnalysisRepo [0:len(VecZ),3*w] = VecZ 
        try: 
            kde_line = axs.lines[-1]
            kde_x = kde_line.get_xdata()
            kde_y = kde_line.get_ydata()
            AnalysisRepo [0:len(kde_x),3*w+1] = kde_x 
            AnalysisRepo [0:len(kde_y),3*w+2] = kde_y 
        except:
            kde_x=np.nan
            kde_y=np.nan
        axsContainer[w] = axs
    return AnalysisRepo, axsContainer
#PopInStatisticalAnalyzer#########################################################################################################################################################################
def PopInStatisticalAnalyzer(Array):
    PopInsExp = np.vstack(Array[:,0,25]).reshape(-1)
    sortedPopInStresses = np.sort(PopInsExp)
    cumDistrPopInStresses = np.cumsum(sortedPopInStresses) / np.sum(sortedPopInStresses)
    idxPopInStresses = (np.abs(cumDistrPopInStresses - 0.5)).argmin()
    return sortedPopInStresses, cumDistrPopInStresses, idxPopInStresses
#ECDFitter########################################################################################################################################################################################
def CumDistFunc(x, t, y):
    return (x[0]*t+x[1])-y
def gen_distr(t, slope, ordinate):      
    yfitted = 1-np.exp(-np.exp(slope*t+ordinate))
    return yfitted 
def ecdfitter(cumprobVector, xVector):  
    idxBot = np.abs(cumprobVector - 0.1).argmin()
    idxTop = np.abs(cumprobVector - 0.7).argmin()
    xecd_fit = xVector[idxBot:idxTop+1]
    yecd_fit = np.log(-1*np.log(1-cumprobVector[idxBot:idxTop+1]))
    ecd_lsq = least_squares(CumDistFunc, [1,-10] , args=(xecd_fit, yecd_fit))
    xfitrange = np.linspace(0.8*np.min(xVector), 1.2*np.max(xVector),50)
    fitdist = gen_distr(xfitrange,ecd_lsq.x[0],ecd_lsq.x[1])
    return xecd_fit, ecd_lsq.x[0], ecd_lsq.x[1], fitdist, xfitrange
#StatisticalPlotter###############################################################################################################################################################################   
def StatisticalPlotter(sortPopInStresses, cumDistrPopInStress, indxPopInStresses,xfit, fittdistr, fitparam1, fitparamr, fitparam2, directory, fontfeatures):
    fig, axs = plt.subplots(1,1,figsize=(6, 8.))   
    axs.plot(sortPopInStresses,cumDistrPopInStress,'.b', markerfacecolor="None")
    axs.plot([0.,sortPopInStresses[indxPopInStresses]],[cumDistrPopInStress[indxPopInStresses],cumDistrPopInStress[indxPopInStresses]],'--k')
    axs.plot([sortPopInStresses[indxPopInStresses],sortPopInStresses[indxPopInStresses]],[0.,cumDistrPopInStress[indxPopInStresses]],'--k')
    axs.plot(sortPopInStresses[indxPopInStresses],cumDistrPopInStress[indxPopInStresses],'ok', label = r'$\tau$' + r'$_{50}$' + ' = ' + 
             str(round(sortPopInStresses[indxPopInStresses],2))+' GPa (' + r'$\mu$' + '/' + str(round(44.6/sortPopInStresses[indxPopInStresses],1)) + ')')
    axs.plot(xfit,fittdistr,'-.k', label='Fitted ECD \n'+ r'$v^*$='+'{:.2e}'.format(fitparam1)+r'$nm^3$ ~'+ 
                str(round(fitparamr,1))+'Ω')
    axs.set_xlabel('Pop-In Shear Stress (GPa)',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_xlim(left=np.min(xfit),right=np.max(xfit))
    axs.set_ylabel('ECDF',fontsize=fontfeatures['xylabelFontSize'])
    axs.set_ylim(bottom=-0.1, top=1.1)
    axs.legend(loc="upper left",fontsize=fontfeatures['legendFontSize']) 
    axs.tick_params(axis='both', which='major', direction='in',labelsize=fontfeatures['axTicksFontSize'])
    plt.tight_layout()
    plt.show() 
    plt.savefig(os.path.join(directory,'Plt_ECDFShear_'+os.path.splitext(os.path.basename(directory))[0]), dpi=300, bbox_inches='tight')
    plt.rcParams['svg.fonttype'] = 'none'
    plt.savefig(os.path.join(directory,'Plt_ECDFShear_'+os.path.splitext(os.path.basename(directory))[0]+'.svg'), format = 'svg') 
    return axs 
