def count_strings_with_substring(strings, substring):
    count = 0
    for string in strings:
        if string.startswith(substring):
            count += 1
    return count
##########NaN Remover################################################################################################################################################################################
def remove_nans(array, column_index):
    if array.ndim==1:
        return array[~np.isnan(array)]
    elif array.ndim==2:
        return array[~np.isnan(array[:, column_index])]
#########NumericalIntegrator#########################################################################################################################################################################
def integrator(array):
    integralValue = np.trapz(array[:,1], array[:,0])
    return integralValue
#########R2Computer##################################################################################################################################################################################
def r_squared(y_true, y_pred):
    rss = np.sum((y_true - y_pred)**2)
    tss = np.sum((y_true - np.mean(y_true))**2)
    r2 = 1 - (rss / tss)
    return r2
#########PowerLawFitter##############################################################################################################################################################################
def PowerLawFitter(x, t, y):
    return (x[0]*(t**x[1])+x[2])-y   
#########DataFrame2PickleFileSaver###################################################################################################################################################################
def savedf2pickle(listdf, path_dir, act, mater):
    if 'PostprocessExperiments' in act.replace(" ", ""):
        file_path = path_dir + '/ExpResults_' + mater + '.pkl'
    elif 'CalibrateSphericalTip/MachineCompliance_N≥2ReferenceMaterials[ChudobaMethod(2000)]' in act.replace(" ", ""):
        if any(isinstance(x, float) for x in mater):
            file_path = path_dir + '/Calib_TupleContainer_'+'-'.join(map(str, mater[:-1]))+'_'+str(int(mater[-1]))+'mN.pkl'
        else:
            matsUsed = [item.split('-')[1].split('(')[0] for item in mater]
            file_path = path_dir + '/Calib_TupleContainer_'+'-'.join(map(str, matsUsed))+'.pkl'            
    elif 'CalibrateSphericalTip/MachineCompliance_N≥2ReferenceMaterials[Li(2013)|Avadanii(2025)Methods]' in act.replace(" ", ""):
        file_path = path_dir + '/Calib_TupleContainer_'+'-'.join(map(str, mater))+'.pkl'               
    elif 'CalibrateSphericalTip/MachineCompliance_CalibrationAggregator' in act.replace(" ", ""):
        file_path = path_dir + '/Calib_Master.pkl'
    elif 'CalibrateSphericalTip/MachineCompliance_DirectInput' in act.replace(" ", ""):
        file_path = path_dir + '/Calibration_Master.pkl'
    elif 'AnalyzeIndenterTipImage_Choose' in act.replace(" ", ""):
        file_path = path_dir + '/AnalysedTipImage_'+ mater + '.pkl'
    elif 'AnalyzeResults_Basic' in act.replace(" ", "") or 'AnalyzeResults_Advanced' in act.replace(" ", ""):
        file_path = path_dir + '/AnalysedResults_'+ mater + '.pkl'
    try:
        with open(file_path, 'wb') as file:
            pickle.dump(listdf, file)
    except Exception as e:
        print(f"Error saving list of DataFrames: {e}")
